WITH filtered AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, DATEDIFF(delivered_date, shipped_date) AS days_shipped_date_to_delivered_date FROM shipments WHERE shipped_date >= TO_DATE('2023-07-17') AND carrier IS NOT NULL), with_dims AS (SELECT a.*, b.shipping_fee, b.channel FROM filtered a JOIN orders b ON a.order_id = b.id WHERE b.shipping_fee BETWEEN 19 AND 20), scored AS (SELECT id, carrier, shipped_date, cost, days_shipped_date_to_delivered_date, channel, NTILE(3) OVER (ORDER BY shipping_fee DESC, id) AS shipping_fee_bucket, SUM(cost) OVER (PARTITION BY order_id) AS order_id_sum_cost, SUM(days_shipped_date_to_delivered_date) OVER w_ordered AS cumulative_days_shipped_date_to_delivered_date FROM with_dims WINDOW w_ordered AS (PARTITION BY channel ORDER BY days_shipped_date_to_delivered_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), with_window AS (SELECT s.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM scored s LEFT JOIN promotions pr ON COALESCE(s.channel, 'web') = pr.channel AND s.shipped_date >= pr.starts_on AND s.shipped_date <= DATE_ADD(pr.ends_on, 7)), scored_shipments AS (SELECT id, carrier, shipped_date, cost, days_shipped_date_to_delivered_date, shipping_fee_bucket, order_id_sum_cost, promo_id, discount_pct, NTILE(4) OVER (ORDER BY discount_pct, id, promo_id) AS discount_pct_bucket, FIRST_VALUE(promo_id, TRUE) OVER (PARTITION BY promo_code ORDER BY order_id_sum_cost, id, promo_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_promo_id, AVG(order_id_sum_cost) OVER (PARTITION BY carrier ORDER BY shipped_date, id, promo_id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS order_id_sum_cost_avg_2_prior, NTILE(5) OVER (PARTITION BY promo_code, carrier ORDER BY cumulative_days_shipped_date_to_delivered_date, id, promo_id) AS cumulative_days_shipped_date_to_delivered_date_bucket FROM with_window), with_windows AS (SELECT id, carrier, cost, days_shipped_date_to_delivered_date, shipping_fee_bucket, order_id_sum_cost, promo_id, discount_pct, first_known_promo_id, order_id_sum_cost_avg_2_prior, LAST_VALUE(order_id_sum_cost, TRUE) OVER (PARTITION BY carrier ORDER BY discount_pct_bucket, id, promo_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_order_id_sum_cost, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY first_known_promo_id DESC, id, promo_id) AS seq_no FROM scored_shipments), valid AS (SELECT *, order_id_sum_cost_avg_2_prior + days_shipped_date_to_delivered_date AS order_id_sum_cost_avg_2_prior_plus_days_shipped_date_to_delivered_date, COALESCE(seq_no, 0) AS seq_no_filled FROM with_windows WHERE carrier IS NOT NULL AND order_id_sum_cost BETWEEN 163 AND 475), report AS (SELECT id, carrier, cost, days_shipped_date_to_delivered_date, promo_id, discount_pct, first_known_promo_id, order_id_sum_cost_avg_2_prior, last_known_order_id_sum_cost, CASE WHEN carrier RLIKE '^(FedEx|DHL)$' THEN 'CORE' ELSE 'PRIORITY' END AS carrier_zone FROM valid) SELECT carrier, cost, promo_id, discount_pct, first_known_promo_id, order_id_sum_cost_avg_2_prior, last_known_order_id_sum_cost, CASE WHEN carrier RLIKE '^(UPS|FedEx)$' THEN 'PRIORITY' WHEN carrier RLIKE '^(DHL|Kerry)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS carrier_zone_2 FROM report;
